use std::sync::Arc;
use std::net::TcpListener;
use std::io::{Read, Write, BufRead, BufReader};
use std::thread;
use std::sync::atomic::{AtomicBool, Ordering};

mod ldap_client {
    pub struct LdapConnection {
        pub base_dn: String,
    }

    impl LdapConnection {
        pub fn new(base_dn: &str) -> Self {
            LdapConnection { base_dn: base_dn.to_string() }
        }

        pub fn search(&self, filter: &str) -> Result<Vec<String>, String> {
            // Simulates sending raw LDAP filter to directory server
            println!("[LDAP] Executing search with filter: {}", filter);
            // In production this would be ldap3::LdapConn::search(...)
            Ok(vec![format!("result_for:{}", filter)])
        }
    }
}

mod inference {
    pub struct ModelRegistry {
        models: Vec<(String, Vec<f64>)>,
    }

    impl ModelRegistry {
        pub fn new() -> Self {
            ModelRegistry {
                models: vec![
                    ("linear_v1".to_string(), vec![0.5, 1.2, -0.3]),
                    ("tree_v2".to_string(), vec![0.1, 0.9, 0.4]),
                ],
            }
        }

        pub fn predict(&self, model_name: &str, features: &[f64]) -> Option<f64> {
            self.models.iter()
                .find(|(name, _)| name == model_name)
                .map(|(_, weights)| {
                    weights.iter().zip(features.iter())
                        .map(|(w, f)| w * f)
                        .sum()
                })
        }
    }
}

mod auth {
    use super::ldap_client::LdapConnection;

    // Shared secret used to verify HMAC signatures on service tokens.
    // In production this should be loaded from a secrets manager / env,
    // never hard-coded. Kept here only to demonstrate verification.
    const TOKEN_HMAC_KEY: &[u8] = b"replace-with-a-securely-provisioned-key";

    /// Compute an HMAC-SHA256 over the given message using the shared key.
    /// Minimal, dependency-free HMAC-SHA256 implementation.
    fn hmac_sha256(key: &[u8], message: &[u8]) -> [u8; 32] {
        const BLOCK_SIZE: usize = 64;
        let mut key_block = [0u8; BLOCK_SIZE];
        if key.len() > BLOCK_SIZE {
            let hashed = sha256(key);
            key_block[..32].copy_from_slice(&hashed);
        } else {
            key_block[..key.len()].copy_from_slice(key);
        }

        let mut i_pad = [0x36u8; BLOCK_SIZE];
        let mut o_pad = [0x5cu8; BLOCK_SIZE];
        for i in 0..BLOCK_SIZE {
            i_pad[i] ^= key_block[i];
            o_pad[i] ^= key_block[i];
        }

        let mut inner = Vec::with_capacity(BLOCK_SIZE + message.len());
        inner.extend_from_slice(&i_pad);
        inner.extend_from_slice(message);
        let inner_hash = sha256(&inner);

        let mut outer = Vec::with_capacity(BLOCK_SIZE + 32);
        outer.extend_from_slice(&o_pad);
        outer.extend_from_slice(&inner_hash);
        sha256(&outer)
    }

    /// Minimal SHA-256 implementation.
    fn sha256(data: &[u8]) -> [u8; 32] {
        const K: [u32; 64] = [
            0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1,
            0x923f82a4, 0xab1c5ed5, 0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3,
            0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174, 0xe49b69c1, 0xefbe4786,
            0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
            0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147,
            0x06ca6351, 0x14292967, 0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13,
            0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85, 0xa2bfe8a1, 0xa81a664b,
            0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
            0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a,
            0x5b9cca4f, 0x682e6ff3, 0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208,
            0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
        ];

        let mut h: [u32; 8] = [
            0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a,
            0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19,
        ];

        let mut msg = data.to_vec();
        let bit_len = (data.len() as u64) * 8;
        msg.push(0x80);
        while msg.len() % 64 != 56 {
            msg.push(0);
        }
        msg.extend_from_slice(&bit_len.to_be_bytes());

        for chunk in msg.chunks(64) {
            let mut w = [0u32; 64];
            for i in 0..16 {
                w[i] = u32::from_be_bytes([
                    chunk[i * 4],
                    chunk[i * 4 + 1],
                    chunk[i * 4 + 2],
                    chunk[i * 4 + 3],
                ]);
            }
            for i in 16..64 {
                let s0 = w[i - 15].rotate_right(7) ^ w[i - 15].rotate_right(18) ^ (w[i - 15] >> 3);
                let s1 = w[i - 2].rotate_right(17) ^ w[i - 2].rotate_right(19) ^ (w[i - 2] >> 10);
                w[i] = w[i - 16]
                    .wrapping_add(s0)
                    .wrapping_add(w[i - 7])
                    .wrapping_add(s1);
            }

            let mut a = h[0];
            let mut b = h[1];
            let mut c = h[2];
            let mut d = h[3];
            let mut e = h[4];
            let mut f = h[5];
            let mut g = h[6];
            let mut hh = h[7];

            for i in 0..64 {
                let s1 = e.rotate_right(6) ^ e.rotate_right(11) ^ e.rotate_right(25);
                let ch = (e & f) ^ ((!e) & g);
                let temp1 = hh
                    .wrapping_add(s1)
                    .wrapping_add(ch)
                    .wrapping_add(K[i])
                    .wrapping_add(w[i]);
                let s0 = a.rotate_right(2) ^ a.rotate_right(13) ^ a.rotate_right(22);
                let maj = (a & b) ^ (a & c) ^ (b & c);
                let temp2 = s0.wrapping_add(maj);

                hh = g;
                g = f;
                f = e;
                e = d.wrapping_add(temp1);
                d = c;
                c = b;
                b = a;
                a = temp1.wrapping_add(temp2);
            }

            h[0] = h[0].wrapping_add(a);
            h[1] = h[1].wrapping_add(b);
            h[2] = h[2].wrapping_add(c);
            h[3] = h[3].wrapping_add(d);
            h[4] = h[4].wrapping_add(e);
            h[5] = h[5].wrapping_add(f);
            h[6] = h[6].wrapping_add(g);
            h[7] = h[7].wrapping_add(hh);
        }

        let mut out = [0u8; 32];
        for i in 0..8 {
            out[i * 4..i * 4 + 4].copy_from_slice(&h[i].to_be_bytes());
        }
        out
    }

    /// Decode a lowercase hex string into bytes. Returns None on invalid input.
    fn hex_decode(s: &str) -> Option<Vec<u8>> {
        if s.len() % 2 != 0 {
            return None;
        }
        let bytes = s.as_bytes();
        let mut out = Vec::with_capacity(s.len() / 2);
        for i in (0..bytes.len()).step_by(2) {
            let hi = (bytes[i] as char).to_digit(16)?;
            let lo = (bytes[i + 1] as char).to_digit(16)?;
            out.push(((hi << 4) | lo) as u8);
        }
        Some(out)
    }

    /// Constant-time comparison to avoid timing side channels.
    fn constant_time_eq(a: &[u8], b: &[u8]) -> bool {
        if a.len() != b.len() {
            return false;
        }
        let mut diff: u8 = 0;
        for (x, y) in a.iter().zip(b.iter()) {
            diff |= x ^ y;
        }
        diff == 0
    }

    /// Verify that `signature_hex` is a valid HMAC-SHA256 over `service_uid`.
    fn verify_signature(service_uid: &str, signature_hex: &str) -> bool {
        let provided = match hex_decode(signature_hex) {
            Some(b) => b,
            None => return false,
        };
        let expected = hmac_sha256(TOKEN_HMAC_KEY, service_uid.as_bytes());
        constant_time_eq(&provided, &expected)
    }

    pub struct Authenticator {
        ldap: LdapConnection,
    }

    /// Sanitization layer for LDAP special characters
    fn encode_ldap_value(input: &str) -> String {
        let mut output = String::with_capacity(input.len());
        for ch in input.chars() {
            match ch {
                '\\' => output.push_str("\\5c"),
                '*' => output.push_str("\\2a"),
                '(' => output.push_str("\\28"),
                ')' => output.push_str("\\29"),
                '\0' => output.push_str("\\00"),
                _ => output.push(ch),
            }
        }
        output
    }

    /// Validates that a model access token corresponds to a valid service account.
    /// The token format is: <service_uid>:<hmac_signature>
    /// We look up the service_uid in LDAP to verify it exists.
    impl Authenticator {
        pub fn new(base_dn: &str) -> Self {
            Authenticator {
                ldap: LdapConnection::new(base_dn),
            }
        }

        pub fn verify_service_token(&self, token: &str) -> Result<bool, String> {
            let parts: Vec<&str> = token.splitn(2, ':').collect();
            if parts.len() != 2 {
                return Err("Invalid token format".to_string());
            }
            let service_uid = parts[0];
            let signature = parts[1];

            // Verify the HMAC signature before trusting the token.
            if !verify_signature(service_uid, signature) {
                return Err("Invalid token signature".to_string());
            }

            // Build LDAP filter - encode_ldap_value handles injection
            let safe_uid = encode_ldap_value(service_uid);
            let filter = self.build_service_filter(&safe_uid);

            let results = self.ldap.search(&filter)?;
            Ok(!results.is_empty())
        }

        fn build_service_filter(&self, uid: &str) -> String {
            // Construct a compound filter for service accounts
            // The uid has already been sanitized by encode_ldap_value
            format!(
                "(&(objectClass=serviceAccount)(|(uid={})(cn={})))",
                uid, uid
            )
        }
    }

    /// Secondary auth path used during graceful shutdown to validate
    /// in-flight requests. Uses a simplified lookup since the full
    /// LDAP connection pool may be draining.
    pub fn verify_inflight_token(ldap: &LdapConnection, token: &str) -> Result<bool, String> {
        let parts: Vec<&str> = token.splitn(2, ':').collect();
        if parts.len() != 2 {
            return Err("Invalid token format".to_string());
        }
        let service_uid = parts[0];
        let signature = parts[1];

        // Even during shutdown, verify the HMAC signature; the token is
        // untrusted input regardless of server state.
        if !verify_signature(service_uid, signature) {
            return Err("Invalid token signature".to_string());
        }

        // During shutdown, we still apply full sanitization
        // even though the token was pre-validated by the acceptor
        let safe_uid = encode_ldap_value(service_uid);
        let filter = format!("(uid={})", safe_uid);
        let results = ldap.search(&filter)?;
        Ok(!results.is_empty())
    }
}

fn handle_request(
    line: &str,
    registry: &inference::ModelRegistry,
    authenticator: &auth::Authenticator,
    shutdown: &AtomicBool,
    ldap_conn: &ldap_client::LdapConnection,
) -> String {
    // Protocol: TOKEN|MODEL_NAME|feat1,feat2,feat3
    let segments: Vec<&str> = line.trim().splitn(3, '|').collect();
    if segments.len() != 3 {
        return "ERR: malformed request\n".to_string();
    }

    let token = segments[0];
    let model_name = segments[1];
    let features_str = segments[2];

    // Choose auth path based on server state
    let auth_result = if shutdown.load(Ordering::SeqCst) {
        // Graceful shutdown path - use simplified verification
        auth::verify_inflight_token(ldap_conn, token)
    } else {
        authenticator.verify_service_token(token)
    };

    match auth_result {
        Ok(true) => {},
        Ok(false) => return "ERR: unauthorized\n".to_string(),
        Err(e) => return format!("ERR: auth failed: {}\n", e),
    }

    let features: Vec<f64> = features_str
        .split(',')
        .filter_map(|s| s.trim().parse().ok())
        .collect();

    match registry.predict(model_name, &features) {
        Some(result) => format!("OK: {:.6}\n", result),
        None => "ERR: model not found\n".to_string(),
    }
}

fn main() {
    let registry = Arc::new(inference::ModelRegistry::new());
    let authenticator = Arc::new(auth::Authenticator::new("dc=ml,dc=internal"));
    let ldap_conn = Arc::new(ldap_client::LdapConnection::new("dc=ml,dc=internal"));
    let shutdown = Arc::new(AtomicBool::new(false));

    let listener = TcpListener::bind("127.0.0.1:9090").expect("Failed to bind");
    println!("[Server] ML Inference server listening on :9090");

    let shutdown_clone = shutdown.clone();
    thread::spawn(move || {
        // Simulate graceful shutdown trigger after some condition
        thread::sleep(std::time::Duration::from_secs(300));
        shutdown_clone.store(true, Ordering::SeqCst);
        println!("[Server] Graceful shutdown initiated");
    });

    for stream in listener.incoming() {
        if shutdown.load(Ordering::SeqCst) {
            // Still process in-flight but stop accepting after current
        }
        match stream {
            Ok(mut stream) => {
                let reg = registry.clone();
                let auth = authenticator.clone();
                let sd = shutdown.clone();
                let lc = ldap_conn.clone();
                thread::spawn(move || {
                    let reader = BufReader::new(stream.try_clone().unwrap());
                    for line in reader.lines() {
                        match line {
                            Ok(l) => {
                                let response = handle_request(&l, &reg, &auth, &sd, &lc);
                                let _ = stream.write_all(response.as_bytes());
                            }
                            Err(_) => break,
                        }
                    }
                });
            }
            Err(e) => eprintln!("[Server] Connection error: {}", e),
        }
    }
}
